(6337681, 937971, 51269, '<td valign="top">This is so much pure fun to look at !!! Excellent in every way -</td>', 'This is so much pure fun to look at !!! Excellent in every way -', '2011-03-01 19:25:15.000000', NULL, 1),
(6337682, 935187, 60047, '<td valign="top">I really love the combination of three elements - the landing position of the bird, the contrast of the  form of the bridge, and the look of the falling snow. I wish the bridge were less orange in its redness - or perhaps selectively desaturated a bit since the color really dominates the overall composition. If the bridge were less orange and dominating - I would say this could contend for a ribbon. Beautiful shot.</td>', 'I really love the combination of three elements - the landing position of the bird, the contrast of the  form of the bridge, and the look of the falling snow. I wish the bridge were less orange in its redness - or perhaps selectively desaturated a bit since the color really dominates the overall composition. If the bridge were less orange and dominating - I would say this could contend for a ribbon. Beautiful shot.', '2011-03-01 19:25:29.000000', NULL, 1),
(6337684, 936972, 60047, '<td valign="top">This shot really has a lot going for it...an uncommon subject (vs a Gull or Eagle), great diagonal pose, nice BG color &amp; bokeh. If I wanted to be picky I''d wish for more crisp definition in the feathers - but that would be picky! Nice work.</td>', 'This shot really has a lot going for it...an uncommon subject (vs a Gull or Eagle), great diagonal pose, nice BG color & bokeh. If I wanted to be picky I''d wish for more crisp definition in the feathers - but that would be picky! Nice work.', '2011-03-01 19:29:32.000000', NULL, 1),
(6337685, 938308, 114285, '<td valign="top">I Like this, it''s almost 3''D ish, it just grabs me.</td>', 'I Like this, it''s almost 3''D ish, it just grabs me.', '2011-03-01 19:29:54.000000', NULL, 1),
(6337686, 936482, 60047, '<td valign="top">Wonderful definition on the skin. Focus is spot on his eye where it should be. Nice composition.</td>', 'Wonderful definition on the skin. Focus is spot on his eye where it should be. Nice composition.', '2011-03-01 19:30:47.000000', NULL, 1),
