(6338002, 938027, 23484, '<td valign="top">Wow, that is definitely frigid looking.</td>', 'Wow, that is definitely frigid looking.', '2011-03-01 23:06:29.000000', NULL, 1),
(6338003, 938096, 60047, '<td valign="top">Not well camouflaged is he? Good that you managed the light on his darkness. He could have easily been underexposed in this harsh light.</td>', 'Not well camouflaged is he? Good that you managed the light on his darkness. He could have easily been underexposed in this harsh light.', '2011-03-01 23:07:24.000000', NULL, 1),
(6338006, 937434, 60047, '<td valign="top">I love the idea of the really low POV.</td>', 'I love the idea of the really low POV.', '2011-03-01 23:08:03.000000', NULL, 1),
(6338007, 938536, 60047, '<td valign="top">The sun appears to be exploding the clouds away! Nice capture.</td>', 'The sun appears to be exploding the clouds away! Nice capture.', '2011-03-01 23:08:45.000000', NULL, 1),
(6338009, 936232, 115307, '<td valign="top">I believe that this is one of those abstract "non-eye candy" shots that everyone can appreciate, whether they favor this form of photography or not. This is art. The movement, feeling, and yes sound, is beautiful. Masterfully done 8</td>', 'I believe that this is one of those abstract "non-eye candy" shots that everyone can appreciate, whether they favor this form of photography or not. This is art. The movement, feeling, and yes sound, is beautiful. Masterfully done 8', '2011-03-01 23:09:51.000000', NULL, 1),
(6338010, 937542, 60047, '<td valign="top">Great detail in the snow. A tad bit too dark for my taste, though. The light on the tree bark really makes this shot work well.</td>', 'Great detail in the snow. A tad bit too dark for my taste, though. The light on the tree bark really makes this shot work well.', '2011-03-01 23:09:53.000000', NULL, 1),
(6338013, 937359, 60047, '<td valign="top">Looks really yummy! Very nice food shot.</td>', 'Looks really yummy! Very nice food shot.', '2011-03-01 23:10:47.000000', NULL, 1),
(6338014, 937856, 60047, '<td valign="top">I can''t help but wonder what that object is in the upper right corner of the shot.</td>', 'I can''t help but wonder what that object is in the upper right corner of the shot.', '2011-03-01 23:12:51.000000', NULL, 1),
(6338015, 937840, 60047, '<td valign="top">Great curves and textures.</td>', 'Great curves and textures.', '2011-03-01 23:13:21.000000', NULL, 1),
(6338016, 936986, 60047, '<td valign="top">Interesting how bright the lights are compared to the darkness of the water.</td>', 'Interesting how bright the lights are compared to the darkness of the water.', '2011-03-01 23:14:03.000000', NULL, 1),
(6338021, 938548, 60047, '<td valign="top">This is a wonderful abstract - a genre I usually don''t connect with. I love the various tensions here - warmth vs cold, blue vs orange, amorphous vs circle. If I had taken this shot, I would print a large version and hang this prominently on a wall of art pieces. Fantastic job.</td>', 'This is a wonderful abstract - a genre I usually don''t connect with. I love the various tensions here - warmth vs cold, blue vs orange, amorphous vs circle. If I had taken this shot, I would print a large version and hang this prominently on a wall of art pieces. Fantastic job.', '2011-03-01 23:18:00.000000', NULL, 1),
(6338024, 937518, 60047, '<td valign="top">One of the better titles I''ve ever seen hear on DPC. Classy. Oh, and the shot is great as well!</td>', 'One of the better titles I''ve ever seen hear on DPC. Classy. Oh, and the shot is great as well!', '2011-03-01 23:19:47.000000', NULL, 1),
(6338031, 937973, 91783, '<td valign="top">what is up with this border?! next time maybe do a solid color, like black or something that compliments the photo nicely. also when it comes to teeth and editing, the final product needs to still look natural.</td>', 'what is up with this border?! next time maybe do a solid color, like black or something that compliments the photo nicely. also when it comes to teeth and editing, the final product needs to still look natural.', '2011-03-01 23:21:23.000000', NULL, 1),
