(6338446, 937608, 25190, '<td valign="top">An amazing image the fog and the bird make it standout i feel that the boarder is tad over done i,m not a fan of this but a lovely image well done</td>', 'An amazing image the fog and the bird make it standout i feel that the boarder is tad over done i,m not a fan of this but a lovely image well done', '2011-03-02 03:50:54.000000', NULL, 1),
(6338447, 938199, 25190, '<td valign="top">Beautiful image love how you have stopped the flow of water wonderful processing ..congrats</td>', 'Beautiful image love how you have stopped the flow of water wonderful processing ..congrats', '2011-03-02 03:50:59.000000', NULL, 1),
(6338448, 938076, 25190, '<td valign="top">Love this i,m a fan of studio portrait images  this is makes me buzz..her eyes for a start are just glued to the lens thats awesome very good art work with the colors and style the wrist bracelet has good effect too ..great shooting good lighting good focus sharp ..super shooting</td>', 'Love this i,m a fan of studio portrait images  this is makes me buzz..her eyes for a start are just glued to the lens thats awesome very good art work with the colors and style the wrist bracelet has good effect too ..great shooting good lighting good focus sharp ..super shooting', '2011-03-02 03:51:20.000000', NULL, 1),
(6338449, 937493, 25190, '<td valign="top">Well capture of the light onto the trees and having the waterflow in motion lovely image</td>', 'Well capture of the light onto the trees and having the waterflow in motion lovely image', '2011-03-02 03:51:24.000000', NULL, 1),
(6338450, 938542, 25190, '<td valign="top">Ann geddes would be so proud of this image a beautiful image baby is in its own little cocoon the eyes have lovely detail wonderful lighting ..well done</td>', 'Ann geddes would be so proud of this image a beautiful image baby is in its own little cocoon the eyes have lovely detail wonderful lighting ..well done', '2011-03-02 03:51:26.000000', NULL, 1),
(6338451, 936213, 25190, '<td valign="top">The lighting of the subject really caught my eye very well done lovely processing colors are well balanced i like how you have him in the image looking away and licking his fingers ..well done</td>', 'The lighting of the subject really caught my eye very well done lovely processing colors are well balanced i like how you have him in the image looking away and licking his fingers ..well done', '2011-03-02 03:51:41.000000', NULL, 1),
