(6338456, 937775, 108069, '<td valign="top">Great still life. Slimey, smelly, cold; nice tones, great composition. Peace in lifeless captivity. Goos stuff.</td>', 'Great still life. Slimey, smelly, cold; nice tones, great composition. Peace in lifeless captivity. Goos stuff.', '2011-03-02 03:57:22.000000', NULL, 1),
(6338458, 933410, 16241, '<td valign="top">man on the moon?</td>', 'man on the moon?', '2011-03-02 03:58:23.000000', NULL, 1),
(6338460, 938363, 108069, '<td valign="top">Nice capture. Well presented in this composition. Would look great in a matted frame (not for this challenge; just saying for later).</td>', 'Nice capture. Well presented in this composition. Would look great in a matted frame (not for this challenge; just saying for later).', '2011-03-02 03:59:38.000000', NULL, 1),
(6338462, 936753, 108069, '<td valign="top">Wow. Stunning shot. Wonderful texture and tones, and incredible exposure range. Fabulous composition. This should do quite well.</td>', 'Wow. Stunning shot. Wonderful texture and tones, and incredible exposure range. Fabulous composition. This should do quite well.', '2011-03-02 04:01:12.000000', NULL, 1),
(6338478, 938076, 108069, '<td valign="top">Wild shot. Oh, and just noticed your title after I wrote that, so nice job on that. Lips could be sharper but a really interesting portrait. Lovely colors, great gaze. Nice job.</td>', 'Wild shot. Oh, and just noticed your title after I wrote that, so nice job on that. Lips could be sharper but a really interesting portrait. Lovely colors, great gaze. Nice job.', '2011-03-02 05:33:30.000000', NULL, 1),
(6338491, 938356, 108069, '<td valign="top">Killer shot. Progression of time through footsteps and transitions and the persistence of the world around us. Wonderful tones, awesome sky. Great stuff.</td>', 'Killer shot. Progression of time through footsteps and transitions and the persistence of the world around us. Wonderful tones, awesome sky. Great stuff.', '2011-03-02 06:00:32.000000', NULL, 1),
(6338493, 935491, 108069, '<td valign="top">Nice, deep, rich colors. Subtlely and artfully lit. Extrememly sincere portrait. Well done.</td>', 'Nice, deep, rich colors. Subtlely and artfully lit. Extrememly sincere portrait. Well done.', '2011-03-02 06:06:04.000000', NULL, 1),
(6338495, 938040, 108069, '<td valign="top">So grainy it''s sped past noisy and stopped at pointillism, and they were all along for the ride. It''s a nice capture of this scene but I think I''d prefer a bit of blur on it to add some mystery. It''s almost too defined and revealing despite the grain. Interesting shot.</td>', 'So grainy it''s sped past noisy and stopped at pointillism, and they were all along for the ride. It''s a nice capture of this scene but I think I''d prefer a bit of blur on it to add some mystery. It''s almost too defined and revealing despite the grain. Interesting shot.', '2011-03-02 06:10:50.000000', NULL, 1),
(6338496, 937511, 108069, '<td valign="top">Wonderfully lit. Excellent focus. Honest and straightforward. Awesome portrait.</td>', 'Wonderfully lit. Excellent focus. Honest and straightforward. Awesome portrait.', '2011-03-02 06:11:41.000000', NULL, 1),
(6338498, 937812, 108069, '<td valign="top">Great composition, vibrant colors, nice scene. Good sutff.</td>', 'Great composition, vibrant colors, nice scene. Good sutff.', '2011-03-02 06:12:22.000000', NULL, 1),
(6338504, 938455, 108069, '<td valign="top">Ah, like the light finally escaping the darkness of winter. I think I''d prefer some more midtones, as this is fairly dark/bright, but it''s an interesting composition and the focal depth ads some mysterious texture.</td>', 'Ah, like the light finally escaping the darkness of winter. I think I''d prefer some more midtones, as this is fairly dark/bright, but it''s an interesting composition and the focal depth ads some mysterious texture.', '2011-03-02 06:32:21.000000', NULL, 1),
(6338505, 937071, 108069, '<td valign="top">Wonderfully sharp. Great light. Nice stuff.</td>', 'Wonderfully sharp. Great light. Nice stuff.', '2011-03-02 06:33:02.000000', NULL, 1),
(6338506, 938518, 108069, '<td valign="top">Nicely captured determination. Nice stop motion to freeze her expression while still getting the essence of motion in her legs and competitor. Good shot.</td>', 'Nicely captured determination. Nice stop motion to freeze her expression while still getting the essence of motion in her legs and competitor. Good shot.', '2011-03-02 06:34:02.000000', NULL, 1),
(6338515, 936652, 108069, '<td valign="top">Nice colors. The angle of perspective is slightly off, so a perfect 90° intersction was impossible with the board and reflection, and I think I would have worked to correct that as best as possible. But it''s different and therefore interesting.</td>', 'Nice colors. The angle of perspective is slightly off, so a perfect 90° intersction was impossible with the board and reflection, and I think I would have worked to correct that as best as possible. But it''s different and therefore interesting.', '2011-03-02 06:53:43.000000', NULL, 1),
(6338521, 938465, 108069, '<td valign="top">Dramatically lit. Silky texture. Exercise or something sinister? Cool portrait.</td>', 'Dramatically lit. Silky texture. Exercise or something sinister? Cool portrait.', '2011-03-02 07:01:22.000000', NULL, 1),
(6338524, 936448, 108069, '<td valign="top">Wonderful colors. Nice composition to get that range with the solid silhouetted foundation of earth. The varying cloud types is also interesting. Lovely photo.</td>', 'Wonderful colors. Nice composition to get that range with the solid silhouetted foundation of earth. The varying cloud types is also interesting. Lovely photo.', '2011-03-02 07:03:19.000000', NULL, 1),
(6338525, 937166, 108069, '<td valign="top">Powerful. Refreshing, cold and sharp. Beautiful photo.</td>', 'Powerful. Refreshing, cold and sharp. Beautiful photo.', '2011-03-02 07:03:28.000000', NULL, 1),
(6338526, 936482, 108069, '<td valign="top">Great focus and focal depth to make an interesting reptile portrait with some character. Beyond the normal. Very well done.</td>', 'Great focus and focal depth to make an interesting reptile portrait with some character. Beyond the normal. Very well done.', '2011-03-02 07:04:18.000000', NULL, 1),
(6338528, 937904, 108069, '<td valign="top">Artsy. Love the high key treatment. Great title. The motion of the mundane portrayed beautifully. Frame accents this. Etching-esque and quite nice.</td>', 'Artsy. Love the high key treatment. Great title. The motion of the mundane portrayed beautifully. Frame accents this. Etching-esque and quite nice.', '2011-03-02 07:06:09.000000', NULL, 1),
(6338535, 936173, 114285, '<td valign="top">No but listening to Mozart does.</td>', 'No but listening to Mozart does.', '2011-03-02 07:19:40.000000', NULL, 1),
