(6341381, 938357, 16148, '<td valign="top">Nicely done!</td>', 'Nicely done!', '2011-03-04 18:41:15.000000', NULL, 1),
(6341382, 938529, 108069, '<td valign="top">Nice focal depth. Quite an interesting object because of the great lighting and shallow depth.</td>', 'Nice focal depth. Quite an interesting object because of the great lighting and shallow depth.', '2011-03-04 18:41:16.000000', NULL, 1),
(6341383, 935187, 16148, '<td valign="top">Love the brilliant red bridge against the cool tones.</td>', 'Love the brilliant red bridge against the cool tones.', '2011-03-04 18:41:21.000000', NULL, 1),
(6341384, 937837, 16148, '<td valign="top">I like your processing of this vast space.</td>', 'I like your processing of this vast space.', '2011-03-04 18:41:37.000000', NULL, 1),
(6341385, 938183, 16148, '<td valign="top">Great intensity!</td>', 'Great intensity!', '2011-03-04 18:41:43.000000', NULL, 1),
(6341386, 936907, 108069, '<td valign="top">Wonderful photo. So sharp, the depth is truly hard to believe, you must have paid them to parade like that, fantastic composition, lovely colors, should I go on? Outstanding.</td>', 'Wonderful photo. So sharp, the depth is truly hard to believe, you must have paid them to parade like that, fantastic composition, lovely colors, should I go on? Outstanding.', '2011-03-04 18:42:39.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6341387, 937343, 16148, '<td valign="top">Very well done!</td>', 'Very well done!', '2011-03-04 18:43:27.000000', NULL, 1),
(6341388, 936627, 16148, '<td valign="top">Nicely composed and wonderful tones.</td>', 'Nicely composed and wonderful tones.', '2011-03-04 18:44:01.000000', NULL, 1),
(6341389, 938418, 108069, '<td valign="top">Fantastic image. Just awesome. Of its many great qualities, the crop is perfect. It just seems so perfectly framed with no awkward half-a-face going on. Small detail, but it is the difference between a great photo and something that''s truly special. And this is.</td>', 'Fantastic image. Just awesome. Of its many great qualities, the crop is perfect. It just seems so perfectly framed with no awkward half-a-face going on. Small detail, but it is the difference between a great photo and something that''s truly special. And this is.', '2011-03-04 18:45:28.000000', NULL, 1),
(6341391, 938356, 16148, '<td valign="top">Strange effect here as if the tide has become clouds.</td>', 'Strange effect here as if the tide has become clouds.', '2011-03-04 18:48:12.000000', NULL, 1),
(6341395, 937977, 108069, '<td valign="top">Awesome. Great lead into the photo, wonderful composition and tones and colors and depth. Killer shot.</td>', 'Awesome. Great lead into the photo, wonderful composition and tones and colors and depth. Killer shot.', '2011-03-04 18:56:56.000000', NULL, 1),
(6341396, 936945, 16148, '<td valign="top">Very interesting.  Might be cleaner if you cropped a little more from the bottom just below the bright paint stripe.  I like it either way.  Good luck!</td>', 'Very interesting.  Might be cleaner if you cropped a little more from the bottom just below the bright paint stripe.  I like it either way.  Good luck!', '2011-03-04 18:57:38.000000', NULL, 1),
(6341397, 937815, 108069, '<td valign="top">Incredible capture. Head and eyes are insanely sharp. Truly awesome.</td>', 'Incredible capture. Head and eyes are insanely sharp. Truly awesome.', '2011-03-04 18:57:49.000000', NULL, 1),
(6341398, 938349, 108069, '<td valign="top">Nicely composed. Nice tones.</td>', 'Nicely composed. Nice tones.', '2011-03-04 18:58:44.000000', NULL, 1),
(6341399, 937364, 108069, '<td valign="top">Nice scene. I like the muted tones.</td>', 'Nice scene. I like the muted tones.', '2011-03-04 18:59:08.000000', NULL, 1),
(6341400, 937720, 108069, '<td valign="top">Cool portrait. Nice eye focus through the smoke.</td>', 'Cool portrait. Nice eye focus through the smoke.', '2011-03-04 18:59:56.000000', NULL, 1),
(6341401, 937339, 108069, '<td valign="top">Great composition with the silhouette and rocks and all the rest. Excellent choice with the subtle colors/tones. I would have tweaked it into stupidness. Wonderful image.</td>', 'Great composition with the silhouette and rocks and all the rest. Excellent choice with the subtle colors/tones. I would have tweaked it into stupidness. Wonderful image.', '2011-03-04 19:02:39.000000', NULL, 1),
(6341402, 934594, 108069, '<td valign="top">Quite nice. Nice exposure range. I think the horizon could use a slight tweak, but not a big deal. Sausalito?</td>', 'Quite nice. Nice exposure range. I think the horizon could use a slight tweak, but not a big deal. Sausalito?', '2011-03-04 19:04:46.000000', NULL, 1),
(6341403, 938414, 108069, '<td valign="top">I have to say this isn''t technically wonderful, and it''s not where technical is purposely thrown to the wind either (it seems to be in that place in between; that mistake* place), but I am continuously drawn to this image. There is something about it that is so genuine, so real, yet a dream. Her action and the position of the incoming light, with it shining through her sweater and highlighting the tops of the grass. It feels like this is maybe part of my life, or I just found it in some Sonic Youth liner notes. Pretty awesome.<br/> <br/>*I know this isn''t a mistake, so don''t take that the wrong way, but you know the images.</td>', 'I have to say this isn''t technically wonderful, and it''s not where technical is purposely thrown to the wind either (it seems to be in that place in between; that mistake* place), but I am continuously drawn to this image. There is something about it that is so genuine, so real, yet a dream. Her action and the position of the incoming light, with it shining through her sweater and highlighting the tops of the grass. It feels like this is maybe part of my life, or I just found it in some Sonic Youth liner notes. Pretty awesome. *I know this isn''t a mistake, so don''t take that the wrong way, but you know the images.', '2011-03-04 19:11:53.000000', NULL, 1),
(6341404, 935452, 108069, '<td valign="top">Fantastic motion blur around the lights. Great composition and exposure. Cool (no pun I swear!) photo.</td>', 'Fantastic motion blur around the lights. Great composition and exposure. Cool (no pun I swear!) photo.', '2011-03-04 19:12:50.000000', NULL, 1),
(6341405, 938355, 108069, '<td valign="top">Adorable photo. The stacked eyes are incredible. Great focus, sharp and clear processing. Very nice.</td>', 'Adorable photo. The stacked eyes are incredible. Great focus, sharp and clear processing. Very nice.', '2011-03-04 19:13:31.000000', NULL, 1),
(6341406, 933651, 108069, '<td valign="top">Great image. Nicely composed, super sharp at just the right spot and some popping colors. Great stuff.</td>', 'Great image. Nicely composed, super sharp at just the right spot and some popping colors. Great stuff.', '2011-03-04 19:14:18.000000', NULL, 1),
(6341407, 938096, 108069, '<td valign="top">Nice contrast. In the wild I don''t imagine he''d last long standing out like that. Cute shot.</td>', 'Nice contrast. In the wild I don''t imagine he''d last long standing out like that. Cute shot.', '2011-03-04 19:15:30.000000', NULL, 1),
(6341409, 938313, 108069, '<td valign="top">Great stuff, sir. Great to see you back with a bang. Nicely color coordinated, by the way. Always impressive technicals and another head-scratcher. Very well done.<br/> <br/>Oh, and awesome title.</td>', 'Great stuff, sir. Great to see you back with a bang. Nicely color coordinated, by the way. Always impressive technicals and another head-scratcher. Very well done. Oh, and awesome title.', '2011-03-04 19:18:00.000000', NULL, 1),
(6341412, 935187, 108069, '<td valign="top">Lovely image. So delicate yet there are pops of color/contrast here and there. Well captured moment and nicely framed. Well done.</td>', 'Lovely image. So delicate yet there are pops of color/contrast here and there. Well captured moment and nicely framed. Well done.', '2011-03-04 19:19:09.000000', NULL, 1),
(6341413, 938509, 108069, '<td valign="top">Great shallow depth: a lot of depth implied but out of focus. Perfect treatment for a little girl that is likely living entirely in the now and really can''t imagine the future yet at all. Cute shot.</td>', 'Great shallow depth: a lot of depth implied but out of focus. Perfect treatment for a little girl that is likely living entirely in the now and really can''t imagine the future yet at all. Cute shot.', '2011-03-04 19:21:19.000000', NULL, 1),
(6341416, 938554, 108069, '<td valign="top">Great capture. Detailed foreground, mysterious mist over the water, serious leading line over the sea, excellent lunar illumination, STARS, nice colors. Awesome exposure management. Wonderful photo. And I personally need to know where this is for a couple reasons.</td>', 'Great capture. Detailed foreground, mysterious mist over the water, serious leading line over the sea, excellent lunar illumination, STARS, nice colors. Awesome exposure management. Wonderful photo. And I personally need to know where this is for a couple reasons.', '2011-03-04 19:21:58.000000', NULL, 1),
(6341417, 934847, 108069, '<td valign="top">Full to the brim with emotion. I can feel his sadness from here.</td>', 'Full to the brim with emotion. I can feel his sadness from here.', '2011-03-04 19:22:07.000000', NULL, 1),
(6341418, 938034, 108069, '<td valign="top">Great composition and colors. Very nice photo.</td>', 'Great composition and colors. Very nice photo.', '2011-03-04 19:23:41.000000', NULL, 1),
(6341419, 938478, 108069, '<td valign="top">Very nice. Perfect focus and sharpness. Professional presentation. Extremely well lit. Great portrait.</td>', 'Very nice. Perfect focus and sharpness. Professional presentation. Extremely well lit. Great portrait.', '2011-03-04 19:23:47.000000', NULL, 1),
(6341422, 938560, 108069, '<td valign="top">Excellent exposure management. Beautiful scene. Cold and alone, stuck out there when the clouds roll in. Nicely done.</td>', 'Excellent exposure management. Beautiful scene. Cold and alone, stuck out there when the clouds roll in. Nicely done.', '2011-03-04 19:24:54.000000', NULL, 1),
(6341423, 937853, 108069, '<td valign="top">Really interesting photo. One of those images that you just have to know more about. What is the story? This will pop into my head for months if not longer. That''s powerful.</td>', 'Really interesting photo. One of those images that you just have to know more about. What is the story? This will pop into my head for months if not longer. That''s powerful.', '2011-03-04 19:26:08.000000', NULL, 1),
(6341425, 935963, 108069, '<td valign="top">Great find. Tons of character. Nice processing, great title. Well done.</td>', 'Great find. Tons of character. Nice processing, great title. Well done.', '2011-03-04 19:33:30.000000', NULL, 1),
(6341427, 938561, 108069, '<td valign="top">Absolutely beautiful. Great colors and tones, super crisp and clean processing, obviously a well spotted scene. The rich colors and sharpness really make this pop. Water is just at that perfect amount of blur. Fantastic.</td>', 'Absolutely beautiful. Great colors and tones, super crisp and clean processing, obviously a well spotted scene. The rich colors and sharpness really make this pop. Water is just at that perfect amount of blur. Fantastic.', '2011-03-04 19:35:12.000000', NULL, 1),
(6341428, 937856, 108069, '<td valign="top">Interesting composition. I like it, but the tones could use some more range and contrast. It seems to be comfortably middle-ground. Maybe a levels adjustment? Not sure. Nice, though.</td>', 'Interesting composition. I like it, but the tones could use some more range and contrast. It seems to be comfortably middle-ground. Maybe a levels adjustment? Not sure. Nice, though.', '2011-03-04 19:36:37.000000', NULL, 1),
(6341435, 938313, 42256, '<td valign="top">You are a genius .. can you be my mentor? ! 10</td>', 'You are a genius .. can you be my mentor? ! 10', '2011-03-04 19:52:24.000000', NULL, 1),
(6341440, 938388, 108069, '<td valign="top">Vibrant, rich colors. Super sharp and clean. Nice composition and just a really nice photo.</td>', 'Vibrant, rich colors. Super sharp and clean. Nice composition and just a really nice photo.', '2011-03-04 20:02:08.000000', NULL, 1),
(6341446, 938098, 76335, '<td valign="top">Tres noir.</td>', 'Tres noir.', '2011-03-04 20:12:37.000000', NULL, 1),
