(6341450, 938058, 76335, '<td valign="top">Wonderful depth and layers.</td>', 'Wonderful depth and layers.', '2011-03-04 20:14:01.000000', NULL, 1),
(6341451, 937514, 92577, '<td valign="top">great moon shot</td>', 'great moon shot', '2011-03-04 20:14:15.000000', NULL, 1),
(6341452, 938202, 76335, '<td valign="top">Beautifully done.</td>', 'Beautifully done.', '2011-03-04 20:14:26.000000', NULL, 1),
(6341453, 937359, 92577, '<td valign="top">sweet - literally!</td>', 'sweet - literally!', '2011-03-04 20:14:40.000000', NULL, 1),
(6341458, 936335, 92577, '<td valign="top">striking image</td>', 'striking image', '2011-03-04 20:16:31.000000', NULL, 1),
(6341459, 937071, 65234, '<td valign="top">Cool capture!  Not the sort of place where I usually find Ospreys perched.</td>', 'Cool capture!  Not the sort of place where I usually find Ospreys perched.', '2011-03-04 20:16:37.000000', NULL, 1),
(6341460, 936668, 76335, '<td valign="top">They make a cute couple. For me, it''s the little glimpses of the little spectators that make this special.</td>', 'They make a cute couple. For me, it''s the little glimpses of the little spectators that make this special.', '2011-03-04 20:16:37.000000', NULL, 1),
(6341461, 938555, 65234, '<td valign="top">Beautiful and peaceful.  Could be eerie, but somehow isn''t striking me that way.</td>', 'Beautiful and peaceful.  Could be eerie, but somehow isn''t striking me that way.', '2011-03-04 20:16:40.000000', NULL, 1),
(6341462, 936807, 65234, '<td valign="top">Perspective makes the graffiti considerably more interesting.</td>', 'Perspective makes the graffiti considerably more interesting.', '2011-03-04 20:17:25.000000', NULL, 1),
(6341463, 934847, 76335, '<td valign="top">The light here adds such wonderful coutnerpoint to an already poignant moment.</td>', 'The light here adds such wonderful coutnerpoint to an already poignant moment.', '2011-03-04 20:18:11.000000', NULL, 1),
(6341464, 938567, 76335, '<td valign="top">That''s one tasty looking orange.</td>', 'That''s one tasty looking orange.', '2011-03-04 20:18:32.000000', NULL, 1),
(6341465, 936972, 65234, '<td valign="top">Pretty bird, and great detail in that eye!</td>', 'Pretty bird, and great detail in that eye!', '2011-03-04 20:18:38.000000', NULL, 1),
(6341467, 935447, 65234, '<td valign="top">Maybe she''s expecting already?  Trying to put a generous spin on her Rubenesque figure ;-)  Nice detail.</td>', 'Maybe she''s expecting already?  Trying to put a generous spin on her Rubenesque figure ;-)  Nice detail.', '2011-03-04 20:19:57.000000', NULL, 1),
(6341468, 938526, 65234, '<td valign="top">Very interesting reflection.</td>', 'Very interesting reflection.', '2011-03-04 20:20:16.000000', NULL, 1),
(6341469, 937339, 65234, '<td valign="top">Kudos to the model for holding still long enough to stay sharp in the final exposure!  Adds a different element to the "long exposure water" shot, which would have been well done without the figure but is very impressive with it.</td>', 'Kudos to the model for holding still long enough to stay sharp in the final exposure!  Adds a different element to the "long exposure water" shot, which would have been well done without the figure but is very impressive with it.', '2011-03-04 20:22:55.000000', NULL, 1),
