(6341862, 935490, 98339, '<td valign="top">colors IMO are pushed way to far...this has a very odd glow to it</td>', 'colors IMO are pushed way to far...this has a very odd glow to it', '2011-03-05 09:45:05.000000', NULL, 1),
(6341864, 937815, 98339, '<td valign="top">I sooooo would have bumped this up in my scoring if you had done curves (or another application of curves) as the feathers of the Eagle are very dull/flat in tone...beautiful capture</td>', 'I sooooo would have bumped this up in my scoring if you had done curves (or another application of curves) as the feathers of the Eagle are very dull/flat in tone...beautiful capture', '2011-03-05 09:46:21.000000', NULL, 1),
(6341868, 937504, 98339, '<td valign="top">focus is way to soft IMO</td>', 'focus is way to soft IMO', '2011-03-05 09:47:04.000000', NULL, 1),
(6341871, 938513, 98339, '<td valign="top">I guess I''m just an o''l fart...the nudity in this just doesn''t float my boat...sorry...no offense intended</td>', 'I guess I''m just an o''l fart...the nudity in this just doesn''t float my boat...sorry...no offense intended', '2011-03-05 09:48:37.000000', NULL, 1),
(6341898, 938098, 23484, '<td valign="top">Two is better than one. Nice grainy b&amp;w.</td>', 'Two is better than one. Nice grainy b&w.', '2011-03-05 10:14:28.000000', NULL, 1),
(6341900, 938018, 23484, '<td valign="top">I like the darkness and the vignetting is nice.</td>', 'I like the darkness and the vignetting is nice.', '2011-03-05 10:16:36.000000', NULL, 1),
(6341901, 936777, 23484, '<td valign="top">Very nice tropical feel.</td>', 'Very nice tropical feel.', '2011-03-05 10:17:11.000000', NULL, 1),
