(6341904, 938308, 23484, '<td valign="top">Very nice composition and leading lines.</td>', 'Very nice composition and leading lines.', '2011-03-05 10:19:07.000000', NULL, 1),
(6341905, 938542, 23484, '<td valign="top">Very nice baby shot.</td>', 'Very nice baby shot.', '2011-03-05 10:19:37.000000', NULL, 1),
(6341906, 938040, 23484, '<td valign="top">Wow, very nice street shot and fantastic high grain.9</td>', 'Wow, very nice street shot and fantastic high grain.9', '2011-03-05 10:20:13.000000', NULL, 1),
(6341907, 938357, 23484, '<td valign="top">That''s the perfect subject for a fisheye. Great job.</td>', 'That''s the perfect subject for a fisheye. Great job.', '2011-03-05 10:21:04.000000', NULL, 1),
