(6341909, 938191, 23484, '<td valign="top">That is one great looking burger.</td>', 'That is one great looking burger.', '2011-03-05 10:22:38.000000', NULL, 1),
(6341912, 937941, 23484, '<td valign="top">Very nice. Perfectly composed. 8</td>', 'Very nice. Perfectly composed. 8', '2011-03-05 10:25:17.000000', NULL, 1),
(6341915, 938418, 23484, '<td valign="top">This is really cool.</td>', 'This is really cool.', '2011-03-05 10:27:05.000000', NULL, 1),
(6341925, 938326, 44611, '<td valign="top">An excellent macro if a rather horrid subject!</td>', 'An excellent macro if a rather horrid subject!', '2011-03-05 10:34:40.000000', NULL, 1),
(6341927, 935856, 44611, '<td valign="top">Good detail, perhaps a little dark. Love the very natural expression.  Good processing too.</td>', 'Good detail, perhaps a little dark. Love the very natural expression.  Good processing too.', '2011-03-05 10:36:17.000000', NULL, 1),
(6341931, 934607, 44611, '<td valign="top">Reflections are a personal favourite subject and this is lovely.  I like the way you''ve kept some of the blue water in as the colours really work together.</td>', 'Reflections are a personal favourite subject and this is lovely.  I like the way you''ve kept some of the blue water in as the colours really work together.', '2011-03-05 10:37:48.000000', NULL, 1),
(6341933, 937594, 44611, '<td valign="top">Excellent leading lines, both the pier and the surf.  I like that you''ve not overworked this - it seems very natural.</td>', 'Excellent leading lines, both the pier and the surf.  I like that you''ve not overworked this - it seems very natural.', '2011-03-05 10:38:29.000000', NULL, 1),
(6341935, 936283, 44611, '<td valign="top">Excellent macro and lovely colours.</td>', 'Excellent macro and lovely colours.', '2011-03-05 10:38:54.000000', NULL, 1),
(6341936, 938561, 44611, '<td valign="top">Beautiful light and colours.  Good work on the water.  Sharp elsewhere.</td>', 'Beautiful light and colours.  Good work on the water.  Sharp elsewhere.', '2011-03-05 10:39:29.000000', NULL, 1),
(6341938, 938523, 44611, '<td valign="top">You are lucky enough to have either very tame deer or a great lens!  Good shot with excellent dof.</td>', 'You are lucky enough to have either very tame deer or a great lens!  Good shot with excellent dof.', '2011-03-05 10:40:28.000000', NULL, 1),
(6341940, 938603, 44611, '<td valign="top">Perhaps a bit overprocessed for my liking but a very interesting shot.</td>', 'Perhaps a bit overprocessed for my liking but a very interesting shot.', '2011-03-05 10:41:30.000000', NULL, 1),
(6341941, 933410, 44611, '<td valign="top">I like this abstract although I''ve no idea what it was originally!  But very interesting.</td>', 'I like this abstract although I''ve no idea what it was originally!  But very interesting.', '2011-03-05 10:42:14.000000', NULL, 1),
(6341944, 938488, 44611, '<td valign="top">Terrific reflection shot.</td>', 'Terrific reflection shot.', '2011-03-05 10:42:26.000000', NULL, 1),
(6341945, 937760, 44611, '<td valign="top">Great repetitive pattern, fab light and works very well in b &amp; w.  I like this.</td>', 'Great repetitive pattern, fab light and works very well in b & w.  I like this.', '2011-03-05 10:43:06.000000', NULL, 1),
(6341947, 937654, 44611, '<td valign="top">Very clever work and looks great in black and white.  Sharp and good lighting.</td>', 'Very clever work and looks great in black and white.  Sharp and good lighting.', '2011-03-05 10:44:02.000000', NULL, 1),
(6341949, 934762, 44611, '<td valign="top">Great street shot - works well in b &amp; w.</td>', 'Great street shot - works well in b & w.', '2011-03-05 10:44:24.000000', NULL, 1),
(6341950, 938587, 44611, '<td valign="top">I love woods and this works very well in b &amp; w.</td>', 'I love woods and this works very well in b & w.', '2011-03-05 10:44:43.000000', NULL, 1),
(6341954, 938199, 44611, '<td valign="top">What a fascinating spot.  Love this in b &amp; w.</td>', 'What a fascinating spot.  Love this in b & w.', '2011-03-05 10:46:38.000000', NULL, 1),
(6341955, 938538, 44611, '<td valign="top">I''m not a fan of over processing, although in some cases it really does work and this is one of them. Even the slightly overexposed patches seem to fit here.</td>', 'I''m not a fan of over processing, although in some cases it really does work and this is one of them. Even the slightly overexposed patches seem to fit here.', '2011-03-05 10:46:48.000000', NULL, 1),
(6341956, 938140, 44611, '<td valign="top">Loe the colours and effect. Good lighting and exposure.</td>', 'Loe the colours and effect. Good lighting and exposure.', '2011-03-05 10:47:30.000000', NULL, 1),
(6341957, 938601, 44611, '<td valign="top">Very DPC friendly!   A lovely place and good shot.</td>', 'Very DPC friendly!   A lovely place and good shot.', '2011-03-05 10:47:55.000000', NULL, 1),
(6341959, 937581, 44611, '<td valign="top">This really tells a story.  Good shot.</td>', 'This really tells a story.  Good shot.', '2011-03-05 10:49:11.000000', NULL, 1),
(6341960, 938418, 44611, '<td valign="top">Love the pattern effect, wish the top half of the shot wasn''t quite so dark - would like to see more detail there.  Still a great shot though.</td>', 'Love the pattern effect, wish the top half of the shot wasn''t quite so dark - would like to see more detail there.  Still a great shot though.', '2011-03-05 10:49:16.000000', NULL, 1),
(6341962, 938308, 44611, '<td valign="top">I really like this - good leading lines and very natural.</td>', 'I really like this - good leading lines and very natural.', '2011-03-05 10:49:44.000000', NULL, 1),
(6341963, 938355, 44611, '<td valign="top">My favourite shot in this challenge.  Great detail, good depth of field and a lovely subject.</td>', 'My favourite shot in this challenge.  Great detail, good depth of field and a lovely subject.', '2011-03-05 10:54:10.000000', NULL, 1),
(6341964, 938183, 44611, '<td valign="top">This is just brilliant.  The enthusiasm of the dogs screams at you.  A great capture.</td>', 'This is just brilliant.  The enthusiasm of the dogs screams at you.  A great capture.', '2011-03-05 10:54:15.000000', NULL, 1),
(6341965, 937339, 44611, '<td valign="top">Fab colours, love the stillness of the water - it looks like mist and a great silhouette.</td>', 'Fab colours, love the stillness of the water - it looks like mist and a great silhouette.', '2011-03-05 10:54:19.000000', NULL, 1),
(6341966, 937010, 44611, '<td valign="top">Fabulously sharp, great exposure - such a shame that one horn is cut off. One of my absolute favourites in this challenge.</td>', 'Fabulously sharp, great exposure - such a shame that one horn is cut off. One of my absolute favourites in this challenge.', '2011-03-05 10:54:22.000000', NULL, 1),
(6341996, 938393, 114225, '<td valign="top">Very nice mix of softness and details.</td>', 'Very nice mix of softness and details.', '2011-03-05 11:22:08.000000', NULL, 1),
(6341998, 937895, 114225, '<td valign="top">Wonderful expression! Great lighting and depth of field as well.</td>', 'Wonderful expression! Great lighting and depth of field as well.', '2011-03-05 11:22:55.000000', NULL, 1),
(6341999, 936482, 114225, '<td valign="top">Great details in those scales. It''s very cool how he is looking at you.</td>', 'Great details in those scales. It''s very cool how he is looking at you.', '2011-03-05 11:23:26.000000', NULL, 1),
(6342004, 935418, 114225, '<td valign="top">Good scene to use what looks like an HDR technique to bring out all those details in the deep shadows.</td>', 'Good scene to use what looks like an HDR technique to bring out all those details in the deep shadows.', '2011-03-05 11:27:11.000000', NULL, 1),
(6342006, 937166, 114225, '<td valign="top">Great textures and curves.</td>', 'Great textures and curves.', '2011-03-05 11:27:47.000000', NULL, 1),
(6342007, 938482, 114225, '<td valign="top">I really like the processing you used here. The gritty feeling is perfect for the subject.</td>', 'I really like the processing you used here. The gritty feeling is perfect for the subject.', '2011-03-05 11:29:54.000000', NULL, 1),
(6342009, 938550, 114225, '<td valign="top">Cute! Nice use of depth of field and soft lighting. I think this could use some texture in the background somehow (I have been noticing with my all white background photos that if I change it out for something textured it turns out much more interesting).</td>', 'Cute! Nice use of depth of field and soft lighting. I think this could use some texture in the background somehow (I have been noticing with my all white background photos that if I change it out for something textured it turns out much more interesting).', '2011-03-05 11:31:50.000000', NULL, 1),
(6342011, 936768, 114225, '<td valign="top">Great portrait. The mountain in the background tricks the eye into thinking the person is giant. Very cool</td>', 'Great portrait. The mountain in the background tricks the eye into thinking the person is giant. Very cool', '2011-03-05 11:32:38.000000', NULL, 1),
(6342013, 936777, 114225, '<td valign="top">The colors here are so vivid and beautiful. But what makes this really great is the composition you chose. The boat, rope, and rock form a triangle which is a great composition device.</td>', 'The colors here are so vivid and beautiful. But what makes this really great is the composition you chose. The boat, rope, and rock form a triangle which is a great composition device.', '2011-03-05 11:34:01.000000', NULL, 1),
(6342015, 936753, 114225, '<td valign="top">I really enjoy how the driftwood points the eye towards the sun. That helps bring this scene together.</td>', 'I really enjoy how the driftwood points the eye towards the sun. That helps bring this scene together.', '2011-03-05 11:35:33.000000', NULL, 1),
(6342016, 937906, 114225, '<td valign="top">The lighting and composition is spot on.</td>', 'The lighting and composition is spot on.', '2011-03-05 11:36:07.000000', NULL, 1),
(6342017, 935907, 114225, '<td valign="top">The red/blue/yellow in the foreground boats is what makes this photo so nice in my eyes.</td>', 'The red/blue/yellow in the foreground boats is what makes this photo so nice in my eyes.', '2011-03-05 11:36:53.000000', NULL, 1),
(6342018, 937975, 114225, '<td valign="top">The longer I look at it, the more I like it!</td>', 'The longer I look at it, the more I like it!', '2011-03-05 11:37:47.000000', NULL, 1),
(6342019, 938199, 114225, '<td valign="top">Very cool scene. Do I see a hint of blue in here to give it a cool feeling?</td>', 'Very cool scene. Do I see a hint of blue in here to give it a cool feeling?', '2011-03-05 11:40:14.000000', NULL, 1),
(6342020, 937780, 114225, '<td valign="top">Wonderful scene and colors. But what makes this really cool is the details of the plants underwater.</td>', 'Wonderful scene and colors. But what makes this really cool is the details of the plants underwater.', '2011-03-05 11:41:04.000000', NULL, 1),
(6342024, 938308, 114225, '<td valign="top">Great find with nice deep colors. I like how my eye starts at the bottom of the tree, moves up through the branches, then flows through the rest of the scene.</td>', 'Great find with nice deep colors. I like how my eye starts at the bottom of the tree, moves up through the branches, then flows through the rest of the scene.', '2011-03-05 11:44:37.000000', NULL, 1),
(6342025, 938415, 114225, '<td valign="top">Great details and lighting.</td>', 'Great details and lighting.', '2011-03-05 11:46:03.000000', NULL, 1),
(6342027, 937518, 114225, '<td valign="top">I like the soft feeling of this scene. Was that due to high amount of noise reduction?</td>', 'I like the soft feeling of this scene. Was that due to high amount of noise reduction?', '2011-03-05 11:47:10.000000', NULL, 1),
(6342028, 938536, 114225, '<td valign="top">Nice mixture of warm and cool colors</td>', 'Nice mixture of warm and cool colors', '2011-03-05 11:48:03.000000', NULL, 1),
(6342030, 938183, 114225, '<td valign="top">Bwa-hahaha! Hilarious!</td>', 'Bwa-hahaha! Hilarious!', '2011-03-05 11:48:57.000000', NULL, 1),
(6342033, 937953, 114225, '<td valign="top">I like the choice of blue duo-tone. The cool feeling is perfect for this scene.</td>', 'I like the choice of blue duo-tone. The cool feeling is perfect for this scene.', '2011-03-05 11:50:18.000000', NULL, 1),
(6342039, 938535, 114225, '<td valign="top">The contrast of her bright white dress against the decaying building is spectacular.</td>', 'The contrast of her bright white dress against the decaying building is spectacular.', '2011-03-05 11:56:00.000000', NULL, 1),
(6342045, 938542, 114225, '<td valign="top">Cool catch lights in the eyes.</td>', 'Cool catch lights in the eyes.', '2011-03-05 11:59:58.000000', NULL, 1),
(6342049, 937010, 114225, '<td valign="top">I like how you composed this, and captured it in rain/snow to add movement to the still scene.</td>', 'I like how you composed this, and captured it in rain/snow to add movement to the still scene.', '2011-03-05 12:00:48.000000', NULL, 1),
(6342051, 937598, 114225, '<td valign="top">Great vantage point/perspective.</td>', 'Great vantage point/perspective.', '2011-03-05 12:03:40.000000', NULL, 1),
(6342052, 938018, 114225, '<td valign="top">Very unique style for a silhouette.</td>', 'Very unique style for a silhouette.', '2011-03-05 12:06:26.000000', NULL, 1),
(6342132, 938348, 76335, '<td valign="top">I think would have preferred it in black and white, with the sky really dark (a red channel conversion). Still nicely composed with good impact.</td>', 'I think would have preferred it in black and white, with the sky really dark (a red channel conversion). Still nicely composed with good impact.', '2011-03-05 14:20:17.000000', NULL, 1),
(6342133, 938073, 76335, '<td valign="top">Something about the lighthouse doesn''t feel quite right. Almost looks like it''s been superimposed over the scene.</td>', 'Something about the lighthouse doesn''t feel quite right. Almost looks like it''s been superimposed over the scene.', '2011-03-05 14:21:26.000000', NULL, 1),
(6342134, 938372, 76335, '<td valign="top">The catch light is perfect.</td>', 'The catch light is perfect.', '2011-03-05 14:22:09.000000', NULL, 1),
(6342139, 938615, 91496, '<td valign="top">Nice lighting.  I think a crop to just the top 2/3 is a much more powerful image.  The angle and light on her hips and legs is not flattering.</td>', 'Nice lighting.  I think a crop to just the top 2/3 is a much more powerful image.  The angle and light on her hips and legs is not flattering.', '2011-03-05 14:30:35.000000', NULL, 1),
(6342145, 938076, 91496, '<td valign="top">Nice lighting and interesting pose.  The eye works great.  The lips just look too odd.  Perhaps the bracelt on the otther arm to creat a diagonal</td>', 'Nice lighting and interesting pose.  The eye works great.  The lips just look too odd.  Perhaps the bracelt on the otther arm to creat a diagonal', '2011-03-05 14:35:15.000000', NULL, 1),
(6342173, 938377, 113419, '<td valign="top">Pretty light, and I love the line of the greenhouses; combined it makes me want to see what''s growing in there, but to make it more appealing, for me anyway I would have cropped out most of the foreground.</td>', 'Pretty light, and I love the line of the greenhouses; combined it makes me want to see what''s growing in there, but to make it more appealing, for me anyway I would have cropped out most of the foreground.', '2011-03-05 15:02:12.000000', NULL, 1),
(6342178, 937275, 113419, '<td valign="top">lovely black and white, the light here is georgous, the boots are a nice touch that leaves you thinking, "Why are the boots on the handlebars?"  Anytime a photo leaves you thinking is a good sign, means you''ve got some interest in the shot.</td>', 'lovely black and white, the light here is georgous, the boots are a nice touch that leaves you thinking, "Why are the boots on the handlebars?"  Anytime a photo leaves you thinking is a good sign, means you''ve got some interest in the shot.', '2011-03-05 15:04:39.000000', NULL, 1),
(6342179, 938160, 113419, '<td valign="top">this photo seems so silent, great capture of the sunlight on the ground below but still that pop of blue is stunning and adds interest to this image.</td>', 'this photo seems so silent, great capture of the sunlight on the ground below but still that pop of blue is stunning and adds interest to this image.', '2011-03-05 15:05:40.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6342181, 938607, 113419, '<td valign="top">This is an awesome image!</td>', 'This is an awesome image!', '2011-03-05 15:06:44.000000', NULL, 1),
(6342185, 938543, 113419, '<td valign="top">What a precious image.  It captures innocense and the lose of innocense in one fell swoop.  The sweetness of a baby and the roughness of a man.  But ironicly all the roughness is lost in this moment.  This image touches my heart.</td>', 'What a precious image.  It captures innocense and the lose of innocense in one fell swoop.  The sweetness of a baby and the roughness of a man.  But ironicly all the roughness is lost in this moment.  This image touches my heart.', '2011-03-05 15:09:07.000000', NULL, 1),
(6342186, 938415, 113419, '<td valign="top">nice piece of symmetry work here</td>', 'nice piece of symmetry work here', '2011-03-05 15:10:30.000000', NULL, 1),
(6342190, 937656, 113419, '<td valign="top">I think this is really a beautiful image.  And I think it would have been an outstanding image had you cropped out the fence which would have also gotten ride of the piled up dirty snow and left a very clean image.  Though I can also see how leaving the fence line adds interest to the image.</td>', 'I think this is really a beautiful image.  And I think it would have been an outstanding image had you cropped out the fence which would have also gotten ride of the piled up dirty snow and left a very clean image.  Though I can also see how leaving the fence line adds interest to the image.', '2011-03-05 15:16:55.000000', NULL, 1),
(6342218, 934033, 90414, '<td valign="top">Eerie yet beautiful capture! I easily see this on a book cover.</td>', 'Eerie yet beautiful capture! I easily see this on a book cover.', '2011-03-05 16:00:24.000000', NULL, 1),
(6342255, 937581, 76335, '<td valign="top">Good tension between the action inside and the anticipation outside.</td>', 'Good tension between the action inside and the anticipation outside.', '2011-03-05 16:46:23.000000', NULL, 1),
(6342256, 938278, 76335, '<td valign="top">I''m not crazy about the processing, but I do like the scene and the composition.</td>', 'I''m not crazy about the processing, but I do like the scene and the composition.', '2011-03-05 16:47:00.000000', NULL, 1),
(6342257, 938542, 76335, '<td valign="top">Great title. And those pools of blue!</td>', 'Great title. And those pools of blue!', '2011-03-05 16:47:22.000000', NULL, 1),
(6342266, 938425, 94241, '<td valign="top">Beautiful capture.  :)<br/> <br/>Feels a little bit blotchy in the low frequencies, try looking at the image shrunk down a little bit to see it better.  I think a few minutes work brushing in some brightness/contrast adjustments would help make it feel a little more natural to me.</td>', 'Beautiful capture.  :) Feels a little bit blotchy in the low frequencies, try looking at the image shrunk down a little bit to see it better.  I think a few minutes work brushing in some brightness/contrast adjustments would help make it feel a little more natural to me.', '2011-03-05 17:13:16.000000', NULL, 1),
(6342267, 938082, 94241, '<td valign="top">I like the bars of abstract color.<br/> <br/>A little flat, maybe a little dark too.  I''d suggest cranking up the brightness and darkening the vignette.</td>', 'I like the bars of abstract color. A little flat, maybe a little dark too.  I''d suggest cranking up the brightness and darkening the vignette.', '2011-03-05 17:15:35.000000', NULL, 1),
(6342268, 938555, 94241, '<td valign="top">Beautiful colors.  :)<br/> <br/>I think the scrubby brush in front is a bit of a fence between viewer and subject.  It doesn''t lead in like an intentional foreground, it just kind of feels like a barrier.</td>', 'Beautiful colors.  :) I think the scrubby brush in front is a bit of a fence between viewer and subject.  It doesn''t lead in like an intentional foreground, it just kind of feels like a barrier.', '2011-03-05 17:18:12.000000', NULL, 1),
(6342271, 937542, 94241, '<td valign="top">Beautiful scene.  But development feels like an HDR that was pushed too hard, some master control slider turned up too high in tone mapping.</td>', 'Beautiful scene.  But development feels like an HDR that was pushed too hard, some master control slider turned up too high in tone mapping.', '2011-03-05 17:23:15.000000', NULL, 1),
(6342272, 938468, 94241, '<td valign="top">Beautiful.  Gorgeous color.<br/> <br/>In tone though, I feel I want more separation between the foreground and background tones.  It doesn''t catch my attention in the top half of the image, but the bottom left corner the background leaves seem over bright.</td>', 'Beautiful.  Gorgeous color. In tone though, I feel I want more separation between the foreground and background tones.  It doesn''t catch my attention in the top half of the image, but the bottom left corner the background leaves seem over bright.', '2011-03-05 17:25:25.000000', NULL, 1),
(6342274, 938454, 94241, '<td valign="top">I think I see what you were going for, but I feel it just came out muddled, there''s nothing in the image that really seems to be the subject of the photo.  This is partly because the doggie is the same tones as everything else so kind of seems invisible.  It''s also because no one thing is really in perfect focus, there''s nothing to lock the eye onto.</td>', 'I think I see what you were going for, but I feel it just came out muddled, there''s nothing in the image that really seems to be the subject of the photo.  This is partly because the doggie is the same tones as everything else so kind of seems invisible.  It''s also because no one thing is really in perfect focus, there''s nothing to lock the eye onto.', '2011-03-05 17:29:15.000000', NULL, 1),
(6342276, 938517, 94241, '<td valign="top">Great moment.  :)<br/> <br/>I personally would have cropped this different.  I would suggest a 16x9 aspect ratio (to feel more like cinema), and to cut off most of that big white square of paper.  Bringing the bottom edge of the crop in right under the subject''s hands would help emphasize the nearly perfect line made between hand, hand, knee, and foot.  Also, the big white square of paper is brighter than the subject, and grabs attention from her.</td>', 'Great moment.  :) I personally would have cropped this different.  I would suggest a 16x9 aspect ratio (to feel more like cinema), and to cut off most of that big white square of paper.  Bringing the bottom edge of the crop in right under the subject''s hands would help emphasize the nearly perfect line made between hand, hand, knee, and foot.  Also, the big white square of paper is brighter than the subject, and grabs attention from her.', '2011-03-05 17:33:43.000000', NULL, 1),
(6342279, 938586, 94241, '<td valign="top">I like the idea, but I can''t get past the unnatural blobs of color, like the big green/yellow/blue light bulb blob.  It doesn''t feel intentional.</td>', 'I like the idea, but I can''t get past the unnatural blobs of color, like the big green/yellow/blue light bulb blob.  It doesn''t feel intentional.', '2011-03-05 17:35:53.000000', NULL, 1),
(6342371, 934594, 94241, '<td valign="top">It''s a beautiful sunrise and gorgeous control of lighting.  But I feel like the foreground takes too much attention from the background.  That big ol'' trash can is trying to be the center of attention.</td>', 'It''s a beautiful sunrise and gorgeous control of lighting.  But I feel like the foreground takes too much attention from the background.  That big ol'' trash can is trying to be the center of attention.', '2011-03-05 21:17:05.000000', NULL, 1),
(6342373, 936482, 94241, '<td valign="top">Handsome.  :)<br/> <br/>I feel there is not quite enough depth of field to this.  His eye is focused, his shoulder is focused.  The tip of his nose is a tad soft, and the spines going down his neck are very soft.  I really want those first few spines to be as sharp as his eye because they are so important to the silhouette.</td>', 'Handsome.  :) I feel there is not quite enough depth of field to this.  His eye is focused, his shoulder is focused.  The tip of his nose is a tad soft, and the spines going down his neck are very soft.  I really want those first few spines to be as sharp as his eye because they are so important to the silhouette.', '2011-03-05 21:19:57.000000', NULL, 1),
