(6343099, 938326, 129091, '<td valign="top">Very nice!</td>', 'Very nice!', '2011-03-06 22:10:18.000000', NULL, 1),
(6343110, 937816, 61961, '<td valign="top">Professional job all around!</td>', 'Professional job all around!', '2011-03-06 22:27:31.000000', NULL, 1),
(6343112, 938183, 61961, '<td valign="top">Fun point-of-view and motion capture.</td>', 'Fun point-of-view and motion capture.', '2011-03-06 22:28:09.000000', NULL, 1),
(6343115, 937450, 76335, '<td valign="top">A beautiful shot that didn''t need a border.</td>', 'A beautiful shot that didn''t need a border.', '2011-03-06 22:33:55.000000', NULL, 1),
(6343117, 938386, 76335, '<td valign="top">Cold, cold cattle.</td>', 'Cold, cold cattle.', '2011-03-06 22:34:33.000000', NULL, 1),
(6343121, 937343, 76335, '<td valign="top">Funky and quirky and downright Nixtericious!</td>', 'Funky and quirky and downright Nixtericious!', '2011-03-06 22:35:44.000000', NULL, 1),
(6343122, 938216, 76335, '<td valign="top">This one stopped me in my tracks. Gret feeling of stealth. And, yes, encroachment.</td>', 'This one stopped me in my tracks. Gret feeling of stealth. And, yes, encroachment.', '2011-03-06 22:37:17.000000', NULL, 1),
(6343125, 938414, 76335, '<td valign="top">A little bit of profile would have added a lot.</td>', 'A little bit of profile would have added a lot.', '2011-03-06 22:38:17.000000', NULL, 1),
(6343126, 938344, 76335, '<td valign="top">A stinky still life if there is such a thing. I like it.</td>', 'A stinky still life if there is such a thing. I like it.', '2011-03-06 22:38:44.000000', NULL, 1),
(6343261, 937166, 121949, '<td valign="top">Very nice! I love the detail you were able to capture in the snow. Not an easy task.</td>', 'Very nice! I love the detail you were able to capture in the snow. Not an easy task.', '2011-03-07 00:31:26.000000', NULL, 1),
(6343298, 938326, 24486, '<td valign="top">Stunning macro</td>', 'Stunning macro', '2011-03-07 01:01:16.000000', NULL, 1),
(6343325, 935904, 24486, '<td valign="top">East of Omaha? Great perspective. Good lines. This would make a great entry for the next Vanishing Point challenge</td>', 'East of Omaha? Great perspective. Good lines. This would make a great entry for the next Vanishing Point challenge', '2011-03-07 01:20:53.000000', NULL, 1),
(6343349, 936269, 68504, '<td valign="top">I love this getting in close, and the unusual focus on the paws and the pollenlike yellows.</td>', 'I love this getting in close, and the unusual focus on the paws and the pollenlike yellows.', '2011-03-07 01:54:47.000000', NULL, 1),
(6343350, 937988, 68504, '<td valign="top">oh my darling white cow, oh darling moo, I hear you</td>', 'oh my darling white cow, oh darling moo, I hear you', '2011-03-07 01:59:33.000000', NULL, 1),
(6343372, 937514, 24486, '<td valign="top">Very nicely captured.</td>', 'Very nicely captured.', '2011-03-07 02:53:06.000000', NULL, 1),
(6343375, 937339, 108580, '<td valign="top">Lovely work, great exp and comp, great light too. -1 for some visible barrel distortion (which is accentuated by the cove to the right where water meets cliffs) and might have been corrected in PP. Otherwise up there with the best.</td>', 'Lovely work, great exp and comp, great light too. -1 for some visible barrel distortion (which is accentuated by the cove to the right where water meets cliffs) and might have been corrected in PP. Otherwise up there with the best.', '2011-03-07 02:58:06.000000', NULL, 1),
(6343381, 938183, 24486, '<td valign="top">Fantastic.</td>', 'Fantastic.', '2011-03-07 03:15:00.000000', NULL, 1),
(6343383, 937816, 108580, '<td valign="top">Superb Portrait and BW conversion, great POV, superb focus on not just eyes but lips too!</td>', 'Superb Portrait and BW conversion, great POV, superb focus on not just eyes but lips too!', '2011-03-07 03:24:11.000000', NULL, 1),
(6343384, 937780, 108580, '<td valign="top">Stunning work</td>', 'Stunning work', '2011-03-07 03:24:24.000000', NULL, 1),
(6343405, 935910, 69487, '<td valign="top">I would venture to say these are models.  The same crap covering the wheels is everywhere.  Plastic is evident in the majority of the image.  Plus I know a couple of these cars would have never been scrapped no matter how badly damaged they might have been to start with.</td>', 'I would venture to say these are models.  The same crap covering the wheels is everywhere.  Plastic is evident in the majority of the image.  Plus I know a couple of these cars would have never been scrapped no matter how badly damaged they might have been to start with.', '2011-03-07 04:27:09.000000', NULL, 1),
(6343411, 937988, 119419, '<td valign="top">Arrroooooww love it</td>', 'Arrroooooww love it', '2011-03-07 04:50:32.000000', NULL, 1),
(6343414, 937760, 119419, '<td valign="top">Brilliant</td>', 'Brilliant', '2011-03-07 04:51:41.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6343416, 938326, 119419, '<td valign="top">Hi Roz, scary and so precise ;)</td>', 'Hi Roz, scary and so precise ;)', '2011-03-07 04:55:22.000000', NULL, 1),
(6343417, 938490, 119419, '<td valign="top">Love the grandeur</td>', 'Love the grandeur', '2011-03-07 04:57:31.000000', NULL, 1),
(6343424, 938058, 119419, '<td valign="top">love the irony</td>', 'love the irony', '2011-03-07 05:11:04.000000', NULL, 1),
(6343425, 936900, 119419, '<td valign="top">good light</td>', 'good light', '2011-03-07 05:11:47.000000', NULL, 1),
(6343476, 937762, 108069, '<td valign="top">I really like the treatment here. Nice high key scene. I personally think it would be a bit stronger if the vignette weren''t so severe, but it''s a great image.</td>', 'I really like the treatment here. Nice high key scene. I personally think it would be a bit stronger if the vignette weren''t so severe, but it''s a great image.', '2011-03-07 06:49:57.000000', NULL, 1),
(6343477, 938615, 67258, '<td valign="top">Very pretty - beautiful colour scheme, too.</td>', 'Very pretty - beautiful colour scheme, too.', '2011-03-07 06:51:48.000000', NULL, 1),
(6343479, 935807, 108069, '<td valign="top">Very nice. Great perspective. Works really well that it''s falling away, as it gives it a bit of movement and makes the building more impressive in a way (make sense?). Nice processing as well.</td>', 'Very nice. Great perspective. Works really well that it''s falling away, as it gives it a bit of movement and makes the building more impressive in a way (make sense?). Nice processing as well.', '2011-03-07 06:53:36.000000', NULL, 1),
(6343480, 936213, 108069, '<td valign="top">Great capture. Tons of character. Well done.</td>', 'Great capture. Tons of character. Well done.', '2011-03-07 06:54:03.000000', NULL, 1),
(6343481, 938596, 108069, '<td valign="top">Great capture. Great movement and a beautiful scene.</td>', 'Great capture. Great movement and a beautiful scene.', '2011-03-07 06:54:26.000000', NULL, 1),
(6343482, 935841, 108069, '<td valign="top">Interesting processing. An artistic approach.</td>', 'Interesting processing. An artistic approach.', '2011-03-07 06:54:54.000000', NULL, 1),
(6343484, 938595, 108069, '<td valign="top">Nicely framed. Interesting distribution of snow leaves a nice contrast with the bricks. Not knock-your-socks-off exciting, but a nice photo.</td>', 'Nicely framed. Interesting distribution of snow leaves a nice contrast with the bricks. Not knock-your-socks-off exciting, but a nice photo.', '2011-03-07 06:56:11.000000', NULL, 1),
(6343485, 937816, 67258, '<td valign="top">The styling, the model, the tonal range - all superb.</td>', 'The styling, the model, the tonal range - all superb.', '2011-03-07 06:56:33.000000', NULL, 1),
(6343491, 936945, 67258, '<td valign="top">Amazing light - super composition.</td>', 'Amazing light - super composition.', '2011-03-07 07:00:32.000000', NULL, 1),
(6343495, 933784, 108069, '<td valign="top">Cool shot. Really interesting how the scene is completely realistic but the people inside look like dolls. Nice environmental street scene.</td>', 'Cool shot. Really interesting how the scene is completely realistic but the people inside look like dolls. Nice environmental street scene.', '2011-03-07 07:01:30.000000', NULL, 1),
(6343497, 938344, 108069, '<td valign="top">Great processing. You can see/feel the air between the wilson paint raised on the fuzz and the rubber of the ball. Great composition. Nice still life.</td>', 'Great processing. You can see/feel the air between the wilson paint raised on the fuzz and the rubber of the ball. Great composition. Nice still life.', '2011-03-07 07:02:46.000000', NULL, 1),
(6343500, 938320, 108069, '<td valign="top">Great capture. Excellent focus and stop motion. Perfect composition. Well done.</td>', 'Great capture. Excellent focus and stop motion. Perfect composition. Well done.', '2011-03-07 07:03:33.000000', NULL, 1),
(6343502, 938357, 108069, '<td valign="top">Wow, this is wild. What a cool idea (honestly no pun intended). Nice deep colors and contrast, and I like the astronaut/hiker/whatever. Good stuff.</td>', 'Wow, this is wild. What a cool idea (honestly no pun intended). Nice deep colors and contrast, and I like the astronaut/hiker/whatever. Good stuff.', '2011-03-07 07:04:48.000000', NULL, 1),
(6343510, 937838, 108069, '<td valign="top">He looks huge! So sharp. Wonderful capture through those branches.</td>', 'He looks huge! So sharp. Wonderful capture through those branches.', '2011-03-07 07:12:08.000000', NULL, 1),
(6343511, 938477, 108069, '<td valign="top">Quite nice. Wonderful contrast and tones.</td>', 'Quite nice. Wonderful contrast and tones.', '2011-03-07 07:12:31.000000', NULL, 1),
(6343515, 935299, 108069, '<td valign="top">Nice capture. Great focus. Cute shot.</td>', 'Nice capture. Great focus. Cute shot.', '2011-03-07 07:13:22.000000', NULL, 1),
(6343516, 938610, 108069, '<td valign="top">Really nice composition. The form of lines and curves is really pleasing, and the play of light looks like an inversion of the metal structure. Well spotted scene.</td>', 'Really nice composition. The form of lines and curves is really pleasing, and the play of light looks like an inversion of the metal structure. Well spotted scene.', '2011-03-07 07:17:02.000000', NULL, 1),
(6343520, 938542, 108069, '<td valign="top">Nice high key treatment. Makes it extra pure.</td>', 'Nice high key treatment. Makes it extra pure.', '2011-03-07 07:20:24.000000', NULL, 1),
(6343521, 938531, 108069, '<td valign="top">Nice capture. Pleasing lines and form of the deer. Well done.</td>', 'Nice capture. Pleasing lines and form of the deer. Well done.', '2011-03-07 07:21:08.000000', NULL, 1),
(6343523, 936911, 108069, '<td valign="top">Nice capture, nice bokeh. Could be a tad sharper but I''d imagine this is a decent crop. Nice.</td>', 'Nice capture, nice bokeh. Could be a tad sharper but I''d imagine this is a decent crop. Nice.', '2011-03-07 07:21:43.000000', NULL, 1),
(6343526, 938586, 108069, '<td valign="top">Wonderful shot. Excellent story teling. She''s caught mesmerized by the action of his blurred, working hands. Excellent use of available light. Great stuff.</td>', 'Wonderful shot. Excellent story teling. She''s caught mesmerized by the action of his blurred, working hands. Excellent use of available light. Great stuff.', '2011-03-07 07:23:22.000000', NULL, 1),
(6343530, 938338, 108069, '<td valign="top">Great weathered texture. Soft yet brittle.</td>', 'Great weathered texture. Soft yet brittle.', '2011-03-07 07:24:46.000000', NULL, 1),
(6343534, 937656, 108069, '<td valign="top">Nicely composed. I like the fecnce as a foreground element. Nice contrast between the cool blue in the sky and the pure white snow of the ground. Very nice photo.</td>', 'Nicely composed. I like the fecnce as a foreground element. Nice contrast between the cool blue in the sky and the pure white snow of the ground. Very nice photo.', '2011-03-07 07:25:46.000000', NULL, 1),
(6343536, 938455, 125975, '<td valign="top">So out of focus.  Snow drops are among my favorite flowers too.  The angle of the shot is interesting.</td>', 'So out of focus.  Snow drops are among my favorite flowers too.  The angle of the shot is interesting.', '2011-03-07 07:27:29.000000', NULL, 1),
(6343537, 937544, 108069, '<td valign="top">Well spotted subject. Focus is tough on this subject, as you''ll never get it all in teh focal plane. I think maybe a tighter crop would have gotten more out of the interesting light while also getting rid of some of the distractions.</td>', 'Well spotted subject. Focus is tough on this subject, as you''ll never get it all in teh focal plane. I think maybe a tighter crop would have gotten more out of the interesting light while also getting rid of some of the distractions.', '2011-03-07 07:27:53.000000', NULL, 1),
(6343540, 936887, 125975, '<td valign="top">At first I thought the background was too dark, but after looking at it a bit, I really like it, and love the echo of the deer ears and profile.</td>', 'At first I thought the background was too dark, but after looking at it a bit, I really like it, and love the echo of the deer ears and profile.', '2011-03-07 07:29:36.000000', NULL, 1),
(6343543, 938086, 125975, '<td valign="top">Tons of interest in this shot.</td>', 'Tons of interest in this shot.', '2011-03-07 07:31:21.000000', NULL, 1),
(6343545, 937514, 108069, '<td valign="top">Fantastic detail. Nice how the craters are visible over the line of illumination as well, hichlighting their rims'' elevation. Great shot.</td>', 'Fantastic detail. Nice how the craters are visible over the line of illumination as well, hichlighting their rims'' elevation. Great shot.', '2011-03-07 07:33:46.000000', NULL, 1),
(6343546, 935807, 125975, '<td valign="top">Great perspective, but I can''t help but wonder if it would have been a stronger image if the lower part of the picture had been cropped out.  I find the road running across it and the snow pile rather distracting.  I also find it slightly overprocessed, in my opinion.</td>', 'Great perspective, but I can''t help but wonder if it would have been a stronger image if the lower part of the picture had been cropped out.  I find the road running across it and the snow pile rather distracting.  I also find it slightly overprocessed, in my opinion.', '2011-03-07 07:34:43.000000', NULL, 1),
(6343547, 938391, 125975, '<td valign="top">I think there''s a little too much going on in this shot.</td>', 'I think there''s a little too much going on in this shot.', '2011-03-07 07:35:17.000000', NULL, 1),
(6343550, 938191, 125975, '<td valign="top">This made me smile - I guess I''m hungry.  Really like the DOF here and how sharp the burger is.  I think that the silver food cover thing is a little distracting though, with the blown out highlight. My eye keeps going to it.  Maybe some judicious editing would help that.  Otherwise great shot.</td>', 'This made me smile - I guess I''m hungry.  Really like the DOF here and how sharp the burger is.  I think that the silver food cover thing is a little distracting though, with the blown out highlight. My eye keeps going to it.  Maybe some judicious editing would help that.  Otherwise great shot.', '2011-03-07 07:37:41.000000', NULL, 1),
(6343555, 938454, 125975, '<td valign="top">I don''t think that the idea of shooting through the fence worked here, because there''s not enough distance between it and the subject and it is way too busy for me.</td>', 'I don''t think that the idea of shooting through the fence worked here, because there''s not enough distance between it and the subject and it is way too busy for me.', '2011-03-07 07:40:31.000000', NULL, 1),
(6343557, 938202, 125975, '<td valign="top">extremely interesting subject.  Especially since it''s not color.</td>', 'extremely interesting subject.  Especially since it''s not color.', '2011-03-07 07:41:35.000000', NULL, 1),
(6343560, 938047, 125975, '<td valign="top">I adore this close up - we can even see the drops on his whiskers!!  Amazing shot.</td>', 'I adore this close up - we can even see the drops on his whiskers!!  Amazing shot.', '2011-03-07 07:44:02.000000', NULL, 1),
(6343563, 938343, 125975, '<td valign="top">Fabulous tones here.  Very well done.</td>', 'Fabulous tones here.  Very well done.', '2011-03-07 07:45:54.000000', NULL, 1),
(6343564, 938371, 125975, '<td valign="top">I''m really not sure I see the focus here.  Lot going on, but nothing to catch my eye.</td>', 'I''m really not sure I see the focus here.  Lot going on, but nothing to catch my eye.', '2011-03-07 07:46:38.000000', NULL, 1),
(6343565, 938027, 125975, '<td valign="top">This is wonderful and it is a refreshing contrast to some of the overprocessed images of nature these days.</td>', 'This is wonderful and it is a refreshing contrast to some of the overprocessed images of nature these days.', '2011-03-07 07:47:58.000000', NULL, 1),
(6343566, 936947, 125975, '<td valign="top">Not sharp enough and a little bit overboard on the processing, in my opinion,</td>', 'Not sharp enough and a little bit overboard on the processing, in my opinion,', '2011-03-07 07:49:00.000000', NULL, 1),
(6343567, 938082, 125975, '<td valign="top">Beautifully sharp, and great ribbons of color flowing across.  The tones seem slightly too dark to me though, although it does set a mood.</td>', 'Beautifully sharp, and great ribbons of color flowing across.  The tones seem slightly too dark to me though, although it does set a mood.', '2011-03-07 07:50:18.000000', NULL, 1),
(6343570, 934033, 125975, '<td valign="top">The atmosphere is so heavy I can cut it.  Great image.</td>', 'The atmosphere is so heavy I can cut it.  Great image.', '2011-03-07 07:58:36.000000', NULL, 1),
(6343571, 938614, 125975, '<td valign="top">The flash in the foreground doesn''t work for me here.  I think I would have like it better if the foreground were cropped out.</td>', 'The flash in the foreground doesn''t work for me here.  I think I would have like it better if the foreground were cropped out.', '2011-03-07 08:00:03.000000', NULL, 1),
(6343572, 938468, 125975, '<td valign="top">Lovely curve here and welcomed subject.</td>', 'Lovely curve here and welcomed subject.', '2011-03-07 08:01:41.000000', NULL, 1),
(6343574, 938557, 125975, '<td valign="top">The inclusion of the dog''s entire ears would have improved this image, I think.  Either that or crop tighter.  Find it distracting to have the ears amputated right in the middle.  Given that, though, I love it.</td>', 'The inclusion of the dog''s entire ears would have improved this image, I think.  Either that or crop tighter.  Find it distracting to have the ears amputated right in the middle.  Given that, though, I love it.', '2011-03-07 08:04:48.000000', NULL, 1),
(6343575, 935299, 125975, '<td valign="top">Super title and shot.</td>', 'Super title and shot.', '2011-03-07 08:05:52.000000', NULL, 1),
(6343577, 936992, 125975, '<td valign="top">Love the lines and composition here.  But I think I would like it a lot better if the processing were a little less.  Makes it too busy for me.</td>', 'Love the lines and composition here.  But I think I would like it a lot better if the processing were a little less.  Makes it too busy for me.', '2011-03-07 08:10:14.000000', NULL, 1),
(6343588, 938501, 125975, '<td valign="top">Ooh, the light reflections in her eyes are not right.  Makes a beautiful woman look scary.</td>', 'Ooh, the light reflections in her eyes are not right.  Makes a beautiful woman look scary.', '2011-03-07 08:17:32.000000', NULL, 1),
(6343590, 937686, 125975, '<td valign="top">A little overprocessed for me.</td>', 'A little overprocessed for me.', '2011-03-07 08:18:58.000000', NULL, 1),
(6343594, 938076, 125975, '<td valign="top">While I recognize the skill involved in creating this image, it''s too overboard for me.  But excellent none the less.</td>', 'While I recognize the skill involved in creating this image, it''s too overboard for me.  But excellent none the less.', '2011-03-07 08:21:05.000000', NULL, 1),
(6343598, 938160, 125975, '<td valign="top">Seems overprocessed in my opinion.</td>', 'Seems overprocessed in my opinion.', '2011-03-07 08:24:52.000000', NULL, 1),
(6343600, 938550, 125975, '<td valign="top">Such whimsy in this one.  Love the composition and colors.</td>', 'Such whimsy in this one.  Love the composition and colors.', '2011-03-07 08:25:33.000000', NULL, 1),
(6343618, 936972, 128809, '<td valign="top">Lovely detail, you''ve caught him in just the right pose.</td>', 'Lovely detail, you''ve caught him in just the right pose.', '2011-03-07 08:42:33.000000', NULL, 1),
(6343677, 938548, 108069, '<td valign="top">Pretty awesome. Really interesting photo. Only thing I''d change is the direct center composition, but that''s a small quibble. Nice stuff.</td>', 'Pretty awesome. Really interesting photo. Only thing I''d change is the direct center composition, but that''s a small quibble. Nice stuff.', '2011-03-07 09:08:10.000000', NULL, 1),
(6343687, 938162, 108069, '<td valign="top">Really nice tones, nice composition, gret detail. I''d go bigger, but that''s it. Well done.</td>', 'Really nice tones, nice composition, gret detail. I''d go bigger, but that''s it. Well done.', '2011-03-07 09:09:56.000000', NULL, 1),
(6343696, 936283, 108069, '<td valign="top">The Dorito Moth? Lovely colors and composition. Great focus. Very nice.</td>', 'The Dorito Moth? Lovely colors and composition. Great focus. Very nice.', '2011-03-07 09:11:14.000000', NULL, 1),
(6343714, 938555, 63218, '<td valign="top">this reminds me of you-know-who</td>', 'this reminds me of you-know-who', '2011-03-07 09:14:21.000000', NULL, 1),
(6343716, 938612, 108069, '<td valign="top">Cool photo. Great tones. The contrast of modern architechture/design vs. natural surroundings is quite cool. I''d give the horizon a bit of a kick, but it''s a great photo.</td>', 'Cool photo. Great tones. The contrast of modern architechture/design vs. natural surroundings is quite cool. I''d give the horizon a bit of a kick, but it''s a great photo.', '2011-03-07 09:14:36.000000', NULL, 1),
(6343772, 938469, 108069, '<td valign="top">Great sky. Very nicely processed to get a realistically exposed shot with great tones and colors. Nice.</td>', 'Great sky. Very nicely processed to get a realistically exposed shot with great tones and colors. Nice.', '2011-03-07 09:24:47.000000', NULL, 1),
(6343775, 935053, 108069, '<td valign="top">Beautifully framed shot. Nice contrast and tones. Poetic title. Wonderful photo.</td>', 'Beautifully framed shot. Nice contrast and tones. Poetic title. Wonderful photo.', '2011-03-07 09:26:10.000000', NULL, 1),
(6343777, 937758, 108069, '<td valign="top">Cute photo. Could be sharper, but it''s more about the bonding and emotions and not the technical.</td>', 'Cute photo. Could be sharper, but it''s more about the bonding and emotions and not the technical.', '2011-03-07 09:27:14.000000', NULL, 1),
(6343794, 934762, 108069, '<td valign="top">Great environmental portrait. Great scene. Nice textures and tones. Great shot.</td>', 'Great environmental portrait. Great scene. Nice textures and tones. Great shot.', '2011-03-07 09:38:56.000000', NULL, 1),
(6343798, 938535, 108069, '<td valign="top">Well lit. Different scene with her satiny clothing not matching the environment. Nice.</td>', 'Well lit. Different scene with her satiny clothing not matching the environment. Nice.', '2011-03-07 09:40:31.000000', NULL, 1),
(6343802, 938556, 108069, '<td valign="top">Passionate photo. Energy and movement.</td>', 'Passionate photo. Energy and movement.', '2011-03-07 09:41:26.000000', NULL, 1),
(6343807, 937608, 108069, '<td valign="top">Stunning shot. Love the tones and the contrast of branches and mist. Bird a nice touch. Great stuff.</td>', 'Stunning shot. Love the tones and the contrast of branches and mist. Bird a nice touch. Great stuff.', '2011-03-07 09:42:28.000000', NULL, 1),
(6343818, 938427, 29748, '<td valign="top">very pretty</td>', 'very pretty', '2011-03-07 09:43:50.000000', NULL, 1),
(6343820, 938531, 29748, '<td valign="top">Excellent timing</td>', 'Excellent timing', '2011-03-07 09:44:21.000000', NULL, 1),
(6343821, 938027, 29748, '<td valign="top">So pretty</td>', 'So pretty', '2011-03-07 09:44:27.000000', NULL, 1),
(6343822, 938522, 29748, '<td valign="top">Oh how lovely</td>', 'Oh how lovely', '2011-03-07 09:44:35.000000', NULL, 1),
(6343823, 937656, 29748, '<td valign="top">This is very pretty</td>', 'This is very pretty', '2011-03-07 09:44:50.000000', NULL, 1),
(6343825, 938538, 108069, '<td valign="top">Nice find. I would have gone the other way with it, though. Instead of blown out, I would have gone dark and gloomy, and toned down those colors (slight desat) to really get the age to hit home. It seems just a bit too bright. But still it''s a nice photo with nice composition and good detail.</td>', 'Nice find. I would have gone the other way with it, though. Instead of blown out, I would have gone dark and gloomy, and toned down those colors (slight desat) to really get the age to hit home. It seems just a bit too bright. But still it''s a nice photo with nice composition and good detail.', '2011-03-07 09:45:32.000000', NULL, 1),
