(6345224, 938183, 30364, '<td valign="top">Del, you were in my 7s.  You know what that means!  It''s probably also the first time I have ever scored a blue above 5.  Now you have to create a new voter profile category just for me.</td>', 'Del, you were in my 7s.  You know what that means!  It''s probably also the first time I have ever scored a blue above 5.  Now you have to create a new voter profile category just for me.', '2011-03-08 05:20:36.000000', NULL, 0),
(6345226, 937816, 41746, '<td valign="top">Congrats Paul. Stunning image, well deserved ribbon.</td>', 'Congrats Paul. Stunning image, well deserved ribbon.', '2011-03-08 05:31:12.000000', NULL, 0),
(6345227, 938183, 61315, '<td valign="top">What a fun shot! Anyone who has been to a sled dog race know how much these dogs <b>love</b> to run and the expressions on these faces says it all. Congratulations on a well deserved blue!</td>', 'What a fun shot! Anyone who has been to a sled dog race know how much these dogs love to run and the expressions on these faces says it all. Congratulations on a well deserved blue!', '2011-03-08 05:33:54.000000', NULL, 0),
(6345228, 938601, 61315, '<td valign="top">CONGRATULATIONS William! Beautiful scene and very well shot and processed......as usual! :-)</td>', 'CONGRATULATIONS William! Beautiful scene and very well shot and processed......as usual! :-)', '2011-03-08 05:37:21.000000', NULL, 0),
(6345229, 938183, 114969, '<td valign="top">I have to agree, these ones really seem to enjoy their time :-) Great work on the timing, especially with those beasts running towards you! Congratulations.</td>', 'I have to agree, these ones really seem to enjoy their time :-) Great work on the timing, especially with those beasts running towards you! Congratulations.', '2011-03-08 05:38:13.000000', NULL, 0),
(6345230, 938601, 114969, '<td valign="top">I love how the motion leads to the light, and how the rocks contrast with it. Greatly composed. Congratulations on the ribbon!</td>', 'I love how the motion leads to the light, and how the rocks contrast with it. Greatly composed. Congratulations on the ribbon!', '2011-03-08 05:39:26.000000', NULL, 0),
(6345231, 937816, 114969, '<td valign="top">The lighting is fantastic. It conveys the softness and the fragility of the situation so well. Congratulations on your well deserved ribbon!</td>', 'The lighting is fantastic. It conveys the softness and the fragility of the situation so well. Congratulations on your well deserved ribbon!', '2011-03-08 05:46:00.000000', NULL, 0),
(6345232, 938326, 114969, '<td valign="top">Such shot is abominably hard to take well, I am very impressed. Congratulations on this well deserved finish!</td>', 'Such shot is abominably hard to take well, I am very impressed. Congratulations on this well deserved finish!', '2011-03-08 05:49:33.000000', NULL, 0),
(6345235, 938313, 61315, '<td valign="top">Congratulations on 5th! Your creativity and dedication to creating your visualized image are amazing! <br/> <br/>This should have scored much higher and again I cannot think of any <b>good</b> reason for those low votes. :-(</td>', 'Congratulations on 5th! Your creativity and dedication to creating your visualized image are amazing!  This should have scored much higher and again I cannot think of any good reason for those low votes. :-(', '2011-03-08 06:26:39.000000', NULL, 0),
