(6345337, 938326, 117474, '<td valign="top">I was going to say this in my initial comment, but figured I''d wait until the challenge was over in case I might embarrass myself :)<br/>I reckon this could have put breakfast on the fly in the red-ribbon position if they were both in the same competition. 4th for a bug macro in a free study. <br/>Superb shot.</td>', 'I was going to say this in my initial comment, but figured I''d wait until the challenge was over in case I might embarrass myself :)I reckon this could have put breakfast on the fly in the red-ribbon position if they were both in the same competition. 4th for a bug macro in a free study. Superb shot.', '2011-03-08 08:56:21.000000', NULL, 0),
(6345338, 937450, 100831, '<td valign="top">I looked at this so many times and tried to find the right words but to no avail. Actually I''m surprised to realize I never commented.... I love it - the dark abstraction, the beautiful lines nature creates while it''s resting... waiting to be absorbed.</td>', 'I looked at this so many times and tried to find the right words but to no avail. Actually I''m surprised to realize I never commented.... I love it - the dark abstraction, the beautiful lines nature creates while it''s resting... waiting to be absorbed.', '2011-03-08 08:58:56.000000', NULL, 0),
(6345340, 934762, 100831, '<td valign="top">wonderful.... I love every little detail... and you can see them all.<br/>I wish for his business to be better.</td>', 'wonderful.... I love every little detail... and you can see them all.I wish for his business to be better.', '2011-03-08 09:00:44.000000', NULL, 0),
(6345341, 938602, 113591, '<td valign="top">What an image. Best is the feeling that the bird has morphed out of the cloud, which is bursting from the mountain, which rose out of the earth.</td>', 'What an image. Best is the feeling that the bird has morphed out of the cloud, which is bursting from the mountain, which rose out of the earth.', '2011-03-08 09:03:34.000000', NULL, 0),
(6345343, 937973, 110108, '<td valign="top">@Jason, I feel a lot of people are dpc-type casted.<br/>we hate when a border is "different", we hate when rule of third is missed by 1/2 a cm and so on.<br/> <br/>I still think the border is good.I had printed this pic and gifted to my friend with a colored frame resembling the border here. Everyone like it...<br/> <br/>Basically people only noted the border, no one cared about the expression caught or the lack of contrast. <br/>To me those were the two key things...<br/> <br/>This photo does NOT deserve 4.5, so I am just taking +ve out of it :)<br/> <br/>In general, I have learned everything here and I appreciate/respect their feedback.</td>', '@Jason, I feel a lot of people are dpc-type casted.we hate when a border is "different", we hate when rule of third is missed by 1/2 a cm and so on. I still think the border is good.I had printed this pic and gifted to my friend with a colored frame resembling the border here. Everyone like it... Basically people only noted the border, no one cared about the expression caught or the lack of contrast. To me those were the two key things... This photo does NOT deserve 4.5, so I am just taking +ve out of it :) In general, I have learned everything here and I appreciate/respect their feedback.', '2011-03-08 09:06:05.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6345345, 937450, 113591, '<td valign="top">The image just presents more possibilities and stories each time I look at it.</td>', 'The image just presents more possibilities and stories each time I look at it.', '2011-03-08 09:12:10.000000', NULL, 0),
(6345347, 937760, 113591, '<td valign="top">The spotlights and windows vie for attention, My eyes can''t decide which is to be the focus. Totally and marvelously confusing.</td>', 'The spotlights and windows vie for attention, My eyes can''t decide which is to be the focus. Totally and marvelously confusing.', '2011-03-08 09:15:23.000000', NULL, 0),
(6345350, 938601, 101117, '<td valign="top">Standing in the water were you? Nicely done :)</td>', 'Standing in the water were you? Nicely done :)', '2011-03-08 09:21:20.000000', NULL, 0),
(6345351, 937010, 51269, '<td valign="top">AH, peter , you''re still here &amp; what a fantastic image- congrats my friend !</td>', 'AH, peter , you''re still here & what a fantastic image- congrats my friend !', '2011-03-08 09:22:48.000000', NULL, 0),
(6345353, 938468, 63218, '<td valign="top">Beautiful. And beautifully done. All the flowers are sharp &amp; crisp against the dull brown leaf litter. Sounds simple, but it isn''t.  It could be that the reason why the votes were mostly in the middle is that people have seen just exactly this flash of color in the spring &amp; have a picture of it in their memory, so it''s familiar. Wish it had done better, but oh well. I was your other 10, I love it.</td>', 'Beautiful. And beautifully done. All the flowers are sharp & crisp against the dull brown leaf litter. Sounds simple, but it isn''t.  It could be that the reason why the votes were mostly in the middle is that people have seen just exactly this flash of color in the spring & have a picture of it in their memory, so it''s familiar. Wish it had done better, but oh well. I was your other 10, I love it.', '2011-03-08 09:26:20.000000', NULL, 0),
(6345355, 937971, 51269, '<td valign="top">Wooo Hooo !!!! Congratulations Buddy !</td>', 'Wooo Hooo !!!! Congratulations Buddy !', '2011-03-08 09:27:38.000000', NULL, 0),
(6345357, 936335, 5885, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Ja-9:</b></div><hr/><i> 2) tones...would be very interested in what you used for the B&amp;W conversion... </i></td></tr></table> <br/> <br/>Alien Skins Exposure. I made a custom preset for a book I made for the couple, based on some photos she had shown me that she liked.</td>', 'Originally posted by Ja-9: 2) tones...would be very interested in what you used for the B&W conversion...   Alien Skins Exposure. I made a custom preset for a book I made for the couple, based on some photos she had shown me that she liked.', '2011-03-08 09:29:42.000000', NULL, 0),
