(6347353, 938216, 119419, '<td valign="top">Such depth and fluidity meshed with emotion yet has a distance that maintains your private realm, thanks for sharing.</td>', 'Such depth and fluidity meshed with emotion yet has a distance that maintains your private realm, thanks for sharing.', '2011-03-09 20:47:16.000000', NULL, 0),
(6347361, 936945, 119419, '<td valign="top">I love how we pluck a speck of time and meld it to that something in us that wants expression. Tar, metal, man, tree, light.. everything has a shadow.</td>', 'I love how we pluck a speck of time and meld it to that something in us that wants expression. Tar, metal, man, tree, light.. everything has a shadow.', '2011-03-09 20:51:57.000000', NULL, 0),
