(6348019, 938601, 119747, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by william88:</b></div><hr/><i> <table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by LydiaToo:</b></div><hr/><i> I commented on this earlier today... WHERE did it go?   *sigh*<br/> <br/>Anyway, William, I love the colors here!  Congrats on your FS RIBBON! </i></td></tr></table> <br/> <br/>Probably eaten by frog. </i></td></tr></table> <br/> <br/>I was thinking the exact same thing LOL<br/> <br/>Congrats, great picture</td>', 'Originally posted by william88: Originally posted by LydiaToo: I commented on this earlier today... WHERE did it go?   *sigh* Anyway, William, I love the colors here!  Congrats on your FS RIBBON!   Probably eaten by frog.   I was thinking the exact same thing LOL Congrats, great picture', '2011-03-10 16:03:05.000000', NULL, 0),
(6348062, 935910, 73032, '<td valign="top">I bought my new camera, and was seeing what i could do with just the basic settings. The pic hasn''t been adjusted, just sized. I didn''t dust off the cars, I think it added to the appeal of old beat up cars, going to the crusher. I wanted to have the truck in the pic too, but it was just too much, and I felt like it would have taken away from the cars on the flatbed.</td>', 'I bought my new camera, and was seeing what i could do with just the basic settings. The pic hasn''t been adjusted, just sized. I didn''t dust off the cars, I think it added to the appeal of old beat up cars, going to the crusher. I wanted to have the truck in the pic too, but it was just too much, and I felt like it would have taken away from the cars on the flatbed.', '2011-03-10 17:28:17.000000', NULL, 0),
(6348135, 937760, 30214, '<td valign="top">what a lovely light, Tom!</td>', 'what a lovely light, Tom!', '2011-03-10 18:32:55.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6348137, 937941, 30214, '<td valign="top">excellent composition, reminds me Chagall''s <a href="//mcphersonremodeling.com/wp-content/uploads/2010/08/Chagall_IandTheVillage.jpg" rel="nofollow" target="_blank">Village</a></td>', 'excellent composition, reminds me Chagall''s Village', '2011-03-10 18:35:34.000000', NULL, 0),
(6348453, 936335, 58785, '<td valign="top">Good job man... this is an art :)</td>', 'Good job man... this is an art :)', '2011-03-11 02:11:40.000000', NULL, 0),
(6348641, 934297, 77196, '<td valign="top">I rather like the sharp shadows from the railings. The lighting on this is really nice. I also like how this is right on the border between putting the viewer in the scene and looking at something. It is very easy for me to imagine being there, and about to go up the steps. <br/>IMO, the shot suffers from "litter" - those wonderful man-made objects that are just unsightly in pictures - like the backs of the sign boards on the first landing, and backs of the signs on either side of the beach access. Also, the top of the building in the upper left corner distracts - a bit puzzling, that - does not look like a condo/hotel/resort - mostly featureless. <br/>IMO, I think scoring is getting tougher on dpchallenge over the past 6-9 months. For some reason, scores seem to have dropped about .5 (in other words, an entry that would have scored 5.0000 last year would probably only get about a 4.5000 now - maybe it is just me. My point is that I think this picture would have scored mid-4''s a year ago. <br/>I hope you enjoyed your time at the beach - to my memory, it generally isn''t very warm on the beaches in the NE US this time of year!<br/></td>', 'I rather like the sharp shadows from the railings. The lighting on this is really nice. I also like how this is right on the border between putting the viewer in the scene and looking at something. It is very easy for me to imagine being there, and about to go up the steps. IMO, the shot suffers from "litter" - those wonderful man-made objects that are just unsightly in pictures - like the backs of the sign boards on the first landing, and backs of the signs on either side of the beach access. Also, the top of the building in the upper left corner distracts - a bit puzzling, that - does not look like a condo/hotel/resort - mostly featureless. IMO, I think scoring is getting tougher on dpchallenge over the past 6-9 months. For some reason, scores seem to have dropped about .5 (in other words, an entry that would have scored 5.0000 last year would probably only get about a 4.5000 now - maybe it is just me. My point is that I think this picture would have scored mid-4''s a year ago. I hope you enjoyed your time at the beach - to my memory, it generally isn''t very warm on the beaches in the NE US this time of year!', '2011-03-11 09:43:22.000000', NULL, 0),
(6348680, 937672, 97760, '<td valign="top">Too bad because it was a very original post processing.</td>', 'Too bad because it was a very original post processing.', '2011-03-11 10:56:45.000000', NULL, 0),
